const input = $input.first().json;
const body = input.body || input;
const skillKey = body.skill_key || '';
const promptTemplate = body.prompt_template || '';
const outputSchema = body.expected_output_schema || {};
const evidencePack = body.evidence_pack || {};
const areaCode = body.area_code || 'general';

return [{
  json: {
    ...body,
    skill_key: skillKey,
    prompt_template: promptTemplate,
    output_schema: outputSchema,
    evidence_pack: evidencePack,
    area_code: areaCode
  }
}];

const input = $input.first().json;

const systemPrompt = `Eres un experto en ${input.area_code} para due diligence legal.
Sigue estas instrucciones del skill "${input.skill_key}":

${input.prompt_template}

REGLAS:
- CITA cada afirmación con [SRC-XXX]
- NO inventes fuentes ni datos
- Responde en español
- Sigue el schema de output esperado`;

const userPrompt = `EVIDENCE PACK:\n${JSON.stringify(input.evidence_pack, null, 2)}\n\nOUTPUT SCHEMA ESPERADO:\n${JSON.stringify(input.output_schema, null, 2)}`;

return [{
  json: {
    report_id: input.report_id,
    request_id: input.request_id,
    skill_key: input.skill_key,
    system_prompt: systemPrompt,
    user_prompt: userPrompt,
    output_schema: input.output_schema,
    model: 'default'
  }
}];

const harveyResponse = $input.first().json;
const prevData = $('Prepare Skill Prompt').first().json;
const outputSchema = prevData.output_schema || {};
const rawResponse = harveyResponse.text || harveyResponse.completion || JSON.stringify(harveyResponse);

// Basic schema validation
const requiredKeys = Object.keys(outputSchema);
const warnings = [];
for (const key of requiredKeys) {
  if (!rawResponse.toLowerCase().includes(key.toLowerCase())) {
    warnings.push(`Missing expected section: ${key}`);
  }
}

return [{
  json: {
    report_id: prevData.report_id,
    request_id: prevData.request_id,
    skill_key: prevData.skill_key,
    output: {
      raw_response: rawResponse,
      model_used: harveyResponse.model || 'harvey-default',
      generated_at: new Date().toISOString()
    },
    validation: {
      schema_warnings: warnings,
      passed: warnings.length === 0
    },
    status: 'ok'
  }
}];
